	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestReverse(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"", ""},
		{"a", "a"},
		{"abc", "cba"},
		{"hello", "olleh"},
		{"abba", "abba"},
	}
	for _, tc := range cases {
		got := reverse(tc.in)
		if got != tc.want {
			t.Errorf("reverse(%q) = %q, want %q", tc.in, got, tc.want)
		}
		if len(got) != len(tc.in) {
			t.Errorf("len(reverse(%q)) = %d, want %d", tc.in, len(got), len(tc.in))
		}
	}
}

